use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fmt::Write,fs,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-worker-attribution176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-worker-attribution176";
fn r(s:&str)->PathBuf{Path::new(R).join(s)}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn walk(p:&Path)->Vec<PathBuf>{let mut files=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){files.extend(walk(&p))}else{files.push(p)}}files.sort();files}
fn main(){let v:Value=serde_json::from_slice(&fs::read(r("review.json")).unwrap()).unwrap();assert_eq!(v["passed"],true);let out=Path::new(O);assert!(!out.exists());fs::create_dir_all(out.join("artifacts")).unwrap();for f in["design.md","reading.md","analyze.rs","review.rs","analysis.json","review.json","pins.json","plan.json","publish.rs"]{fs::copy(r(f),out.join("artifacts").join(f)).unwrap();}let mut records=BTreeMap::new();for p in walk(&r("check")){let b=fs::read(&p).unwrap();let text=String::from_utf8(b.clone()).unwrap();assert_eq!(text.as_bytes(),b);records.insert(p.strip_prefix(r("check")).unwrap().display().to_string(),json!({"utf8":text,"length":b.len(),"sha256":hash(&b)}));}for(_,v)in &records{let b=v["utf8"].as_str().unwrap().as_bytes();assert_eq!(hash(b),v["sha256"]);}fs::write(out.join("artifacts/workflow-receipts.json"),serde_json::to_vec_pretty(&records).unwrap()).unwrap();fs::copy(r("report-draft.md"),out.join("README.md")).unwrap();let mut sums=String::new();for p in walk(out){writeln!(sums,"{}  {}",hash(&fs::read(&p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("{}",json!({"public_files":12,"workflow_receipt_members":records.len(),"private_runtime_arrays_binaries_profiles_published":false,"raw_profiles_reused_by_hash_from_parent":true}));}
